func message(for line: String) -> String {
    do {
        let (name, _) = try parse(line)
        return "Добавлено: \(name)"
    } catch EventImportError.invalidDuration {
        return "Проверь длительность"
    } catch EventImportError.emptyName {
        return "Добавь название"
    } catch {
        return "Проверь формат"
    }
}

try помечает бросающий вызов, а catch превращает тип ошибки в действие для пользователя. Последний catch закрывает остальные ошибки.

do {
    _ = try parse("Встреча:abc")
} catch EventImportError.invalidDuration {
    print("Проверь длительность")
} catch {
    print("Проверь формат")
}

try? превратил любую ошибку в nil и стёр причину. do/catch сохраняет различие нужных пользователю случаев.

