let show: (Result<(String, Int), Error>) -> Void = { outcome in
    switch outcome {
    case .success(let item): print("Добавлено: \(item.0)")
    case .failure(let error as EventImportError)
        where error == .invalidDuration:
        print("Проверь длительность")
    case .failure(let error): print("Не добавлено: \(error)")
    }
}
importLine("Встреча:45", onImport: show)
importLine("Встреча:abc", onImport: show)

«Добавлено: Встреча», затем «Проверь длительность». `Result { try parse(line) }` превращает бросающий вызов в значение, которое можно отдать обработчику; ошибка едет внутри `.failure` и разбирается там же, где показывается.

